<?= $this->include('layouts/header') ?><div class="page-head"><div><div class="page-kicker">Report</div><h1 class="page-title">Stock report</h1><p class="page-subtitle">Current ledger balance for every product.</p></div><div class="head-actions"><a class="btn" href="<?=site_url('reports')?>">← Reports</a><a class="btn primary" href="<?=site_url('reports/export/STOCK')?>">Export CSV</a></div></div><div class="card"><div class="table-wrap"><table class="table"><thead><tr><th>Product</th><th>Code</th><th>Unit</th><th>Opening</th><th>Minimum</th><th>Current</th><th>Status</th></tr></thead><tbody><?php if(!$rows): ?><tr><td colspan="7"><div class="empty"><strong>No stock data</strong>Create products to populate this report.</div></td></tr><?php else: foreach($rows as $r): $low=(float)$r['current_stock']<=(float)$r['minimum_stock']; ?><tr><td><strong><?=esc($r['name'])?></strong></td><td class="mono"><?=esc($r['code'])?></td><td><?=esc($r['unit'])?></td><td><?=esc(inventory_quantity_label((float)$r['opening_stock'], (string)$r['unit']))?></td><td><?=esc(inventory_quantity_label((float)$r['minimum_stock'], (string)$r['unit']))?></td><td><strong><?=esc(inventory_quantity_label((float)$r['current_stock'], (string)$r['unit']))?></strong></td><td><span class="badge <?=$low?'danger':'success'?>"><?=$low?'Low stock':'Healthy'?></span></td></tr><?php endforeach; endif; ?></tbody></table></div></div><?= $this->include('layouts/footer') ?>